/**
 * @method
 * @name lighter#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://apidocs.lighter.xyz/reference/candles
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Lighter) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Lighter) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1h")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if false {
		panic(ArgumentsRequired(this.Id + " fetchOHLCV() requires a symbol argument"))
	}
	if this.Markets() == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var until *int64 = this.SafeInteger(params, "until")
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"until"})
	var now int64 = this.Milliseconds()
	var startTs any = nil
	var endTs any = nil
	if since != nil {
		startTs = since
		if until != nil {
			endTs = until
		} else if limit != nil {
			var duration int64 = this.ParseTimeframe(timeframe)
			endTs = this.Sum(since, (duration**limit)*1000)
		} else {
			endTs = now
		}
	} else {
		var count *int64 = this.SafeInteger(map[string]any{
			"limit": limit,
		}, "limit", 100)
		var timeframeMs int64 = this.ParseTimeframe(timeframe) * 1000
		var span int64 = timeframeMs * *count
		if until != nil {
			endTs = until
			startTs = *until - span
		} else {
			endTs = now
			startTs = now - span
		}
	}
	var request map[string]any = map[string]any{
		"market_id":       market["id"],
		"count_back":      0,
		"resolution":      this.SafeString(this.Timeframes, timeframe, timeframe),
		"start_timestamp": startTs,
		"end_timestamp":   endTs,
	}

	r2 := <-this.PublicGetCandles(this.Extend(request, paramsOmitted))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	// {
	//     "code": 200,
	//     "r": "1m",
	//     "c": [
	//         {
	//             "t": 1767700500000,
	//             "o": 3236.86,
	//             "h": 3237.78,
	//             "l": 3235.36,
	//             "c": 3235.39,
	//             "v": 55.1632,
	//             "V": 178530.793575,
	//             "i": 779870452,
	//             "C": "string",
	//             "H": "string",
	//             "L": "string",
	//             "O": "string"
	//         }
	//     ]
	// }
	//
	var ohlcvs []any = SafeListTypedDefault(response, "c", []any{})

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(ohlcvs, market, timeframe, since, limit))}
	return nil
}
