func (this *Lighter) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	r1 := <-this.HandleAccountIndexAsync(params, "fetchBalance", "accountIndex", "account_index")
	if r1.Err != nil {
		panic(r1.Err)
	}
	listRecv2438, _ := r1.Value, r1.Value != nil
	var accountIndexparamsAccountIndexVariable []any = listRecv2438
	accountIndex := accountIndexparamsAccountIndexVariable[0]
	paramsAccountIndex := accountIndexparamsAccountIndexVariable[1]
	var defaultType *string = this.SafeString2(this.Options, "fetchBalance", "defaultType", "spot")
	var typeVar *string = this.SafeString(paramsAccountIndex, "type", defaultType)
	var request map[string]any = map[string]any{
		"by":    this.SafeString(paramsAccountIndex, "by", "index"),
		"value": accountIndex,
	}

	r2 := <-this.PublicGetAccount(this.Extend(request, paramsAccountIndex))
	if r2.Err != nil {
		panic(r2.Err)
	}
	response := r2.Raw
	//
	//     {
	//         "code": "200",
	//         "total": "1",
	//         "accounts": [
	//             {
	//                 "code": "0",
	//                 "account_type": "0",
	//                 "index": "1077",
	//                 "l1_address": "0x15f43D1f2DeE81424aFd891943262aa90F22cc2A",
	//                 "cancel_all_time": "0",
	//                 "total_order_count": "1",
	//                 "total_isolated_order_count": "0",
	//                 "pending_order_count": "0",
	//                 "available_balance": "7996.489834",
	//                 "status": "1",
	//                 "collateral": "9000.000000",
	//                 "account_index": "1077",
	//                 "name": "",
	//                 "description": "",
	//                 "can_invite": true,
	//                 "referral_points_percentage": "",
	//                 "positions": [],
	//                 "assets": [
	//                     {
	//                         "symbol": "ETH",
	//                         "asset_id": "1",
	//                         "balance": "3.00000000",
	//                         "locked_balance": "0.00000000"
	//                     },
	//                     {
	//                         "symbol": "USDC",
	//                         "asset_id": "3",
	//                         "balance": "1000.000000",
	//                         "locked_balance": "0.000000"
	//                     }
	//                 ],
	//                 "total_asset_value": "9536.789088",
	//                 "cross_asset_value": "9536.789088",
	//                 "shares": []
	//             }
	//         ]
	//     }
	//
	var result map[string]any = map[string]any{
		"info": response,
	}
	var accounts []any = SafeListTyped(response, "accounts")
	for i := 0; i < len(accounts); i++ {
		var account map[string]any = SafeMapTyped(accounts, i)
		if typeVar != nil && *typeVar == "spot" {
			var assets []any = SafeListTyped(account, "assets")
			for j := 0; j < len(assets); j++ {
				var asset map[string]any = SafeMapTyped(assets, j)
				var codeId *string = this.SafeString(asset, "symbol")
				var code *string = this.SafeCurrencyCode(codeId)
				var balance map[string]any = this.Extend(this.Account(), this.SafeDict(result, code, map[string]any{}))
				balance["total"] = Precise.StringAdd(balance["total"], this.SafeString(asset, "balance"))
				balance["used"] = Precise.StringAdd(balance["used"], this.SafeString(asset, "locked_balance"))
				if code != nil {
					result[*code] = balance
				}
			}
		} else {
			var perpBalance map[string]any = this.Extend(this.Account(), this.SafeDict(result, "USDC", map[string]any{}))
			var perpTotal *string = this.SafeString(perpBalance, "total", "0")
			var perpFree *string = this.SafeString(perpBalance, "free", "0")
			var perpUSDCTotal *string = this.SafeString(account, "collateral", "0")
			var perpUSDCFree *string = this.SafeString(account, "available_balance", "0")
			perpBalance["total"] = Precise.StringAdd(perpTotal, perpUSDCTotal)
			perpBalance["free"] = Precise.StringAdd(perpFree, perpUSDCFree)
			result["USDC"] = perpBalance
		}
	}

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.SafeBalance(result).(map[string]any))}
	return nil
}

