func (this *Lighter) ParsePosition(position any, optionalArgs ...any) Position {
	//
	//     {
	//         "market_id": 0,
	//         "symbol": "ETH",
	//         "initial_margin_fraction": "5.00",
	//         "open_order_count": 0,
	//         "pending_order_count": 0,
	//         "position_tied_order_count": 0,
	//         "sign": 1,
	//         "position": "18.0193",
	//         "avg_entry_price": "2669.84",
	//         "position_value": "54306.566340",
	//         "unrealized_pnl": "6197.829558",
	//         "realized_pnl": "0.000000",
	//         "liquidation_price": "2191.1107231380406",
	//         "margin_mode": 0,
	//         "allocated_margin": "0.000000"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "market_id")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var sign *int64 = this.SafeInteger(position, "sign")
	var side *string = nil
	if sign != nil {
		side = SafeStringPtr(func() string {
			if sign != nil && *sign == 1 {
				return "long"
			}
			return "short"
		}())
	}
	var marginModeId *int64 = this.SafeInteger(position, "margin_mode")
	var marginMode *string = nil
	if marginModeId != nil {
		marginMode = SafeStringPtr(func() string {
			if marginModeId != nil && *marginModeId == 0 {
				return "cross"
			}
			return "isolated"
		}())
	}
	var imfStr *string = this.SafeString(position, "initial_margin_fraction")
	var leverage any = nil
	if imfStr != nil {
		var imf int64 = this.ParseToInt(imfStr)
		if imf > 0 {
			leverage = Divide(100, imf)
		}
	}
	var contractsString *string = this.SafeString(position, "position")
	var positionValueString *string = this.SafeString(position, "position_value")
	var markPriceString *string = Precise.StringDiv(positionValueString, contractsString)
	// allocated_margin is the isolated collateral balance (0 for cross)
	var positionMargin *float64 = nil
	if marginMode != nil && *marginMode == "isolated" {
		positionMargin = this.SafeNumber(position, "allocated_margin")
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      marketResolved["symbol"],
		"timestamp":                   nil,
		"datetime":                    nil,
		"isolated":                    (marginMode != nil && *marginMode == "isolated"),
		"hedged":                      nil,
		"side":                        side,
		"contracts":                   this.ParseNumber(contractsString),
		"contractSize":                nil,
		"entryPrice":                  this.SafeNumber(position, "avg_entry_price"),
		"markPrice":                   this.ParseNumber(markPriceString),
		"notional":                    this.ParseNumber(positionValueString),
		"leverage":                    leverage,
		"positionMargin":              positionMargin,
		"collateral":                  nil,
		"initialMargin":               nil,
		"maintenanceMargin":           nil,
		"initialMarginPercentage":     nil,
		"maintenanceMarginPercentage": nil,
		"unrealizedPnl":               this.SafeNumber(position, "unrealized_pnl"),
		"liquidationPrice":            this.SafeNumber(position, "liquidation_price"),
		"marginMode":                  marginMode,
		"percentage":                  nil,
	})
}

