func (this *Lighter) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	//     {
	//         "trade_id": 17609,
	//         "tx_hash": "99ffeaa3899fbaa51043840ddf762fd18c182a33b5125092105bee57af11fab04edf5fd90e969abd",
	//         "type": "trade",
	//         "market_id": 0,
	//         "size": "10.2304",
	//         "price": "2958.75",
	//         "usd_amount": "30269.196000",
	//         "ask_id": 281474977339869,
	//         "bid_id": 562949952870533,
	//         "ask_client_id": 0,
	//         "bid_client_id": 0,
	//         "ask_account_id": 20,
	//         "bid_account_id": 1077,
	//         "is_maker_ask": true,
	//         "block_height": 102070,
	//         "timestamp": 1766386112741,
	//         "taker_position_size_before": "0.0000",
	//         "taker_entry_quote_before": "0.000000",
	//         "taker_position_sign_changed": true,
	//         "maker_position_size_before": "-1856.8547",
	//         "maker_entry_quote_before": "5491685.069325",
	//         "maker_initial_margin_fraction_before": 500
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(trade, "market_id")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(trade, "timestamp")
	var accountIndex *string = this.SafeString(trade, "account_index")
	var askAccountId *string = this.SafeString(trade, "ask_account_id")
	var bidAccountId *string = this.SafeString(trade, "bid_account_id")
	var isMakerAsk *bool = this.SafeBool(trade, "is_maker_ask")
	var side *string = nil
	var orderId *string = nil
	if accountIndex != nil {
		if accountIndex == askAccountId || (accountIndex != nil && askAccountId != nil && *accountIndex == *askAccountId) {
			side = SafeStringPtr("sell")
			orderId = this.SafeString(trade, "ask_id")
		} else if accountIndex == bidAccountId || (accountIndex != nil && bidAccountId != nil && *accountIndex == *bidAccountId) {
			side = SafeStringPtr("buy")
			orderId = this.SafeString(trade, "bid_id")
		}
	}
	// public trades use Lighter's taker-side convention
	if (side == nil) && (isMakerAsk != nil) {
		side = SafeStringPtr(func() string {
			if isMakerAsk != nil && *isMakerAsk {
				return "buy"
			}
			return "sell"
		}())
	}
	var takerOrMaker *string = nil
	if (side != nil) && (isMakerAsk != nil) {
		var isMaker any = func() any {
			if side != nil && *side == "sell" {
				return (isMakerAsk != nil && *isMakerAsk == true)
			}
			return (isMakerAsk != nil && *isMakerAsk == false)
		}()
		takerOrMaker = SafeStringPtr(func() string {
			if isMaker == true {
				return "maker"
			}
			return "taker"
		}())
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           this.SafeString(trade, "trade_id"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"order":        orderId,
		"type":         this.SafeString(trade, "type"),
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString(trade, "size"),
		"cost":         this.SafeString(trade, "usd_amount"),
		"fee":          nil,
	}, marketResolved)
}

